fn is_sorted(arr: &Vec<i32>) -> bool {
    // Since arr.len() > 0, start checking from the first element
    // For nondecreasing order, every element must be <= the next element
    for i in 0..arr.len() - 1 {
        if arr[i] > arr[i + 1] {
            return false;
        }
    }
    true
}